'use client'

import type { ComponentProps } from 'react'
import {
  Avatar as UiAvatar,
  AvatarFallback as UiAvatarFallback,
  AvatarImage as UiAvatarImage,
} from '@ui-sdk/react/avatar'

import './avatar.css'

function omit<T extends object, const K extends readonly (keyof T)[]>(
  obj: T,
  ...keys: K
): Omit<T, K[number]> {
  const copy = { ...obj }
  for (const key of keys) delete copy[key]
  return copy
}

/**
 * Avatar, a 1:1 port of opencode's `@opencode/ui` Avatar visuals (MIT):
 * `packages/ui/src/data-display/avatar` (`avatar-v2`, `avatar.css`), on top of
 * ui-sdk's headless Avatar, AvatarImage and AvatarFallback.
 *
 * Styling lives in `avatar.css` as attribute rules (`data-size`, `data-kind`,
 * `data-has-image`), so both kinds and all three sizes match upstream: user
 * avatars are circular, org avatars take a 6px radius (4px at `small` and
 * `normal`), and the boxes are 28, 20 and 16px. Behaviour — the real `<img>`,
 * the fallback while the image loads or after it fails, the fallback `delay`,
 * and the loading status on every part — comes from `@ui-sdk/react`.
 *
 * Upstream is one component taking `src` and `fallback`; ui-sdk splits it into
 * parts, so pass `hasImage` when you render an `AvatarImage`. It is upstream's
 * own `data-has-image` attribute, which drops the fallback's sheen:
 *
 *   <Avatar kind="org" size="small" hasImage>
 *     <AvatarImage src={logo} alt="Acme" />
 *     <AvatarFallback>A</AvatarFallback>
 *   </Avatar>
 *
 * Upstream shows the first grapheme of `fallback`; ui-sdk renders the
 * fallback's children as given, so pass the one or two letters yourself.
 * Upstream's `background` / `foreground` props are inline overrides of
 * `--avatar-bg` / `--avatar-fg`; set those custom properties on `style`
 * instead. ui-sdk's root is a `<span>` where upstream used a `<div>`; the
 * upstream `display: flex` makes the two lay out the same.
 */

export type AvatarKind = 'user' | 'org'
export type AvatarSize = 'large' | 'normal' | 'small'

type UiAvatarProps = ComponentProps<typeof UiAvatar>

export type AvatarProps = Omit<UiAvatarProps, 'className' | 'render'> & {
  /** Circle for `user` (default), rounded corners for `org`. */
  kind?: AvatarKind
  /** 28px (default), 20px or 16px. */
  size?: AvatarSize
  /** Marks that this avatar renders an `AvatarImage`, like upstream's `src`. */
  hasImage?: boolean
  className?: UiAvatarProps['className']
  render?: UiAvatarProps['render']
}

export function Avatar(props: AvatarProps) {
  const rest = omit(props, 'kind', 'size', 'hasImage', 'className', 'render')

  return (
    <UiAvatar
      {...rest}
      className={props.className}
      render={props.render}
      data-kind={props.kind ?? 'user'}
      data-size={props.size ?? 'large'}
      data-has-image={props.hasImage ? '' : undefined}
    />
  )
}

type UiAvatarImageProps = ComponentProps<typeof UiAvatarImage>

export type AvatarImageProps = Omit<UiAvatarImageProps, 'className' | 'render'> & {
  className?: UiAvatarImageProps['className']
  render?: UiAvatarImageProps['render']
}

/** The image, hidden until it loads; the fallback covers it until then. */
export function AvatarImage(props: AvatarImageProps) {
  const rest = omit(props, 'className', 'render')

  return <UiAvatarImage {...rest} className={props.className} render={props.render} />
}

type UiAvatarFallbackProps = ComponentProps<typeof UiAvatarFallback>

export type AvatarFallbackProps = Omit<
  UiAvatarFallbackProps,
  'className' | 'render'
> & {
  className?: UiAvatarFallbackProps['className']
  render?: UiAvatarFallbackProps['render']
}

/** Initials or an icon, shown while no image is loaded. */
export function AvatarFallback(props: AvatarFallbackProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiAvatarFallback {...rest} className={props.className} render={props.render} />
  )
}

/*
 * 1:1 port of opencode's Avatar (`@opencode/ui/avatar`, MIT):
 * packages/ui/src/data-display/avatar/avatar.css.
 *
 * Only the root selector changed, to meet ui-sdk's markup. Every value is
 * upstream: the 16 / 20 / 28px boxes, the circular and 4 / 6px radii, the
 * 0.5px border and the ::before sheen.
 *
 *   [data-component="avatar-v2"]  →  [data-slot="avatar"]  (ui-sdk's root slot)
 *   [data-slot="avatar-image"]    →  same name (ui-sdk already uses it)
 *
 * `data-size` ("small" | "normal" | "large") and `data-kind` ("user" | "org")
 * come from Kitsaas' props; `data-has-image` is upstream's own attribute,
 * exposed as the `hasImage` prop, and drops the sheen once an image is there.
 *
 * Upstream has no [data-color-scheme="dark"] block: the fallback layer,
 * text, border and light-alpha sheen all come from --v2-* tokens that flip
 * with the scheme on their own.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@layer components {
  [data-slot="avatar"] {
    --avatar-bg: var(--v2-background-bg-layer-02);
    --avatar-fg: var(--v2-text-text-muted);
    --avatar-radius: 9999px;
    --avatar-font-size: 11px;
    --avatar-tracking: 0.05px;

    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    position: relative;
    overflow: hidden;
    width: 28px;
    height: 28px;
    border-radius: var(--avatar-radius);
    border: 0.5px solid var(--v2-border-border-base);
    font-weight: 530;
    font-size: var(--avatar-font-size);
    line-height: 1;
    letter-spacing: var(--avatar-tracking);
    text-transform: uppercase;
    background-color: var(--avatar-bg);
    color: var(--avatar-fg);
    user-select: none;
    -webkit-user-select: none;
  }

  [data-slot="avatar"]::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
      180deg,
      var(--v2-alpha-light-16) 0%,
      var(--v2-alpha-light-0) 100%
    );
    pointer-events: none;
  }

  [data-slot="avatar"][data-has-image]::before {
    display: none;
  }

  [data-slot="avatar"][data-kind="org"] {
    --avatar-radius: 6px;
  }

  [data-slot="avatar"][data-kind="org"][data-size="normal"],
  [data-slot="avatar"][data-kind="org"][data-size="small"] {
    --avatar-radius: 4px;
  }

  [data-slot="avatar"][data-size="normal"] {
    width: 20px;
    height: 20px;
  }

  [data-slot="avatar"][data-size="small"] {
    width: 16px;
    height: 16px;
  }

  [data-slot="avatar"] [data-slot="avatar-image"] {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    border-radius: inherit;
    user-select: none;
    -webkit-user-select: none;
    -webkit-user-drag: none;
  }
}
